mapper.select:
SELECT id, biz_type, subject_id, idempotent_key, request_hash, biz_id, status, expire_time, create_time
FROM idempotent_record
WHERE biz_type = #{bizType}
  AND subject_id = #{subjectId}
  AND idempotent_key = #{idempotentKey}
LIMIT 1

mapper.update:
UPDATE idempotent_record
SET status = 1,
    biz_id = #{bizId}
WHERE biz_type = #{bizType}
  AND subject_id = #{subjectId}
  AND idempotent_key = #{idempotentKey}

mapper.delete:
DELETE FROM idempotent_record
WHERE biz_type = #{bizType}
  AND subject_id = #{subjectId}
  AND idempotent_key = #{idempotentKey}
  AND expire_time < #{now}

DELETE FROM idempotent_record
WHERE expire_time < #{now}
LIMIT #{limit}
